     1	package br.com.marealta;
     2	
     3	/** Não envia para endereço inválido: a mensagem fica na lista como bloqueada. */
     4	public class BlockInvalidAddress implements MessageSender {
     5	    private final MessageSender next;
     6	    private final Outbox outbox;
     7	
     8	    public BlockInvalidAddress(MessageSender next, Outbox outbox) {
     9	        this.next = next;
    10	        this.outbox = outbox;
    11	    }
    12	
    13	    @Override
    14	    public void send(OutgoingMessage message) {
    15	        if (isValid(message.to())) {
    16	            next.send(message);
    17	        } else {
    18	            outbox.block(message);
    19	        }
    20	    }
    21	
    22	    /** Um único @, algo antes dele e, depois, um nome com ponto no meio. */
    23	    static boolean isValid(String address) {
    24	        if (address == null || address.chars().anyMatch(Character::isWhitespace)) return false;
    25	        int at = address.indexOf('@');
    26	        if (at < 1 || at != address.lastIndexOf('@')) return false;
    27	        String domain = address.substring(at + 1);
    28	        return domain.indexOf('.') > 0 && !domain.endsWith(".");
    29	    }
    30	}
