=== MessagingSetup
     1	package br.com.marealta;
     2	
     3	import java.util.List;
     4	import java.util.function.UnaryOperator;
     5	
     6	/**
     7	 * Monta a cadeia de regras de envio de uma instalação. Para uma nova regra, basta uma classe
     8	 * decoradora e uma linha em RULES; para outra pousada, basta mudar a lista.
     9	 */
    10	public final class MessagingSetup {
    11	    static final String ARCHIVE_ADDRESS = "arquivo@pousadamarealta.com.br";
    12	    static final String TEST_ADDRESS = "testes@pousadamarealta.com.br";
    13	
    14	    private enum Scope {
    15	        ALWAYS, TEST_ONLY, OUTSIDE_TEST;
    16	
    17	        boolean appliesTo(boolean testMode) {
    18	            return this == ALWAYS || (this == TEST_ONLY) == testMode;
    19	        }
    20	    }
    21	
    22	    private record Rule(Scope scope, UnaryOperator<MessageSender> wrap) {}
    23	
    24	    private MessagingSetup() {}
    25	
    26	    /** Constrói o remetente; a primeira regra aplicável é a mais externa. */
    27	    public static MessageSender build(Outbox outbox, boolean testMode) {
    28	        List<Rule> rules = List.of(
    29	                new Rule(Scope.ALWAYS, next -> new BlockInvalidAddress(next, outbox)),
    30	                new Rule(Scope.OUTSIDE_TEST, next -> new ArchiveCopy(next, ARCHIVE_ADDRESS)),
    31	                new Rule(Scope.TEST_ONLY, next -> new RedirectToTestAddress(next, TEST_ADDRESS)));
    32	
    33	        MessageSender sender = outbox;
    34	        for (Rule rule : rules.reversed()) {
    35	            if (rule.scope().appliesTo(testMode)) {
    36	                sender = rule.wrap().apply(sender);
    37	            }
    38	        }
    39	        return sender;
    40	    }
    41	}
