     6	/** Lista de mensagens enviadas (e bloqueadas); é o fim da cadeia de envio. */
     7	public class Outbox implements MessageSender {
     8	    private final List<SentMessage> messages = new ArrayList<>();
     9	
    10	    @Override
    11	    public synchronized void send(OutgoingMessage message) {
    12	        store(message, MessageStatus.SENT);
    13	    }
    14	
    15	    public synchronized void block(OutgoingMessage message) {
    16	        store(message, MessageStatus.BLOCKED);
    17	    }
    18	
    19	    public synchronized List<SentMessage> messages() {
    20	        return List.copyOf(messages);
    21	    }
    22	
    23	    private void store(OutgoingMessage m, MessageStatus status) {
    24	        messages.add(new SentMessage(messages.size() + 1, m.channel(), m.to(), m.subject(), m.body(), status));
    25	    }
    26	}
