     1	package br.com.marealta;
     2	
     3	import com.fasterxml.jackson.databind.ObjectMapper;
     4	import com.fasterxml.jackson.databind.SerializationFeature;
     5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
     6	import io.javalin.Javalin;
     7	import io.javalin.http.Context;
     8	import java.time.LocalDate;
     9	import java.time.YearMonth;
    10	import java.time.format.DateTimeParseException;
    11	import java.util.Map;
    12	
    13	public class Main {
    14	    private static final ObjectMapper MAPPER = new ObjectMapper()
    15	            .registerModule(new JavaTimeModule())
    16	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    17	
    18	    public static void main(String[] args) {
    19	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
    20	        String port = System.getenv("PORT");
    21	        createApp(testMode).start(port == null || port.isBlank() ? 7070 : Integer.parseInt(port.trim()));
    22	    }
    23	
    24	    static Javalin createApp(boolean testMode) {
    25	        Outbox outbox = new Outbox();
    26	        Hotel hotel = new Hotel(MessagingSetup.build(outbox, testMode));
    27	        Javalin app = Javalin.create();
    28	
    29	        app.get("/rooms", ctx -> json(ctx, 200, hotel.rooms()));
    30	        app.post("/reservations", ctx -> json(ctx, 201,
    31	                ReservationView.of(hotel.reserve(ReservationRequest.parse(MAPPER, ctx.body())))));
    32	        app.get("/reservations/{id}", ctx -> json(ctx, 200, ReservationView.of(hotel.find(ctx.pathParam("id")))));
    33	        app.post("/reservations/{id}/confirmation", ctx ->
    34	                json(ctx, 200, ReservationView.of(hotel.confirm(ctx.pathParam("id")))));
    35	        app.post("/reservations/{id}/cancellation", ctx ->
    36	                json(ctx, 200, ReservationView.of(hotel.cancel(ctx.pathParam("id")))));
    37	        app.post("/reservations/{id}/check-in", ctx ->
    38	                json(ctx, 200, ReservationView.of(hotel.checkIn(ctx.pathParam("id")))));
    39	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, hotel.checkOut(ctx.pathParam("id"))));
    40	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, hotel.document(ctx.pathParam("id"))));
    41	        app.get("/messages", ctx -> json(ctx, 200, outbox.messages()));
    42	        app.get("/reports/occupancy", ctx -> csv(ctx, hotel.occupancyReport(date(ctx.queryParam("date")))));
    43	        app.get("/reports/revenue", ctx -> csv(ctx, hotel.revenueReport(month(ctx.queryParam("month")))));
    44	
    45	        app.exception(DomainException.class, (e, ctx) ->
    46	                json(ctx, e.status(), Map.of("error", e.code(), "message", e.getMessage())));
    47	        app.exception(Exception.class, (e, ctx) -> {
    48	            e.printStackTrace();
    49	            json(ctx, 500, Map.of("error", "INTERNAL_ERROR", "message", "Erro interno"));
    50	        });
    51	        return app;
    52	    }
    53	
    54	    private static LocalDate date(String value) {
    55	        try {
    56	            return LocalDate.parse(value);
    57	        } catch (DateTimeParseException | NullPointerException e) {
    58	            throw DomainException.invalidRequest("date deve estar no formato AAAA-MM-DD");
    59	        }
    60	    }
    61	
    62	    private static YearMonth month(String value) {
    63	        try {
    64	            return YearMonth.parse(value);
    65	        } catch (DateTimeParseException | NullPointerException e) {
    66	            throw DomainException.invalidRequest("month deve estar no formato AAAA-MM");
    67	        }
    68	    }
    69	
    70	    private static void json(Context ctx, int status, Object body) {
    71	        try {
    72	            ctx.status(status).contentType("application/json").result(MAPPER.writeValueAsString(body));
    73	        } catch (Exception e) {
    74	            throw new IllegalStateException(e);
    75	        }
    76	    }
    77	
    78	    private static void csv(Context ctx, String body) {
    79	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
    80	    }
    81	}

