   1	package br.com.marealta;
   2	
   3	import java.time.LocalDate;
   4	import java.time.YearMonth;
   5	import java.util.ArrayList;
   6	import java.util.Comparator;
   7	import java.util.LinkedHashMap;
   8	import java.util.List;
   9	import java.util.Map;
  10	
  11	/** Regras de negócio da pousada, com os dados em memória. */
  12	public class Hotel {
  13	    private static final String CONFIRMATION_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
  14	
  15	    private final List<Room> rooms = List.of(
  16	            Room.of(101, RoomType.STANDARD), Room.of(102, RoomType.STANDARD),
  17	            Room.of(201, RoomType.DELUXE), Room.of(202, RoomType.DELUXE),
  18	            Room.of(301, RoomType.SUITE));
  19	    private final Map<Integer, Reservation> reservations = new LinkedHashMap<>();
  20	    private final MessageSender sender;
  21	
  22	    public Hotel(MessageSender sender) {
  23	        this.sender = sender;
  24	    }
  25	
  26	    public List<Room> rooms() {
  27	        return rooms;
  28	    }
  29	
  30	    synchronized Reservation reserve(ReservationRequest request) {
  31	        Room room = rooms.stream().filter(r -> r.number() == request.roomNumber()).findFirst()
  32	                .orElseThrow(() -> DomainException.roomNotFound(request.roomNumber()));
  33	        if (request.guests() > room.capacity()) {
  34	            throw DomainException.capacityExceeded(room.capacity());
  35	        }
  36	        boolean taken = reservations.values().stream().anyMatch(r -> r.isActive()
  37	                && r.room().number() == room.number() && r.overlaps(request.checkIn(), request.checkOut()));
  38	        if (taken) {
  39	            throw DomainException.roomUnavailable();
  40	        }
  41	        Reservation reservation = new Reservation(reservations.size() + 1, room, request.guestName(),
  42	                request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
  43	                request.guests(), request.ratePlan());
  44	        reservations.put(reservation.id(), reservation);
  45	        return reservation;
